// ========== SEGURANÇA AVANÇADA & PROTEÇÃO ANTI-DEVTOOLS ==========
let lastUserActivity = Date.now();
const INACTIVITY_TIMEOUT = 15 * 60 * 1000; // 15 minutos

(function initSecurity() {
  // 1. Anti-Clickjacking (Framebusting)
  if (window.top !== window.self) {
    try { window.top.location = window.self.location; } catch (e) {}
  }

  // 2. Proteção Anti-Scraping e Anti-Drag
  document.addEventListener('dragstart', function(e) {
    if (e.target.closest('table, .product-card, .parceria-card, .heist-summary-card')) {
      e.preventDefault();
      return false;
    }
  });

  // 3. Bloqueia clique direito (context menu)
  document.addEventListener('contextmenu', function(e) {
    e.preventDefault();
    if (typeof showToast === 'function') showToast('🔒 Menu de contexto desativado por segurança');
    return false;
  });

  // 4. Bloqueia atalhos de DevTools (F12, Ctrl+Shift+I/J/C, Ctrl+U, Ctrl+S)
  document.addEventListener('keydown', function(e) {
    if (
      e.key === 'F12' ||
      e.keyCode === 123 ||
      (e.ctrlKey && e.shiftKey && ['I', 'i', 'J', 'j', 'C', 'c'].includes(e.key)) ||
      (e.ctrlKey && ['u', 'U', 's', 'S'].includes(e.key))
    ) {
      e.preventDefault();
      e.stopPropagation();
      if (typeof showToast === 'function') showToast('🔒 Atalho bloqueado por motivos de segurança');
      return false;
    }
  });

  // 5. Monitorização de Inatividade (Auto-Lock 15 min)
  ['mousemove', 'keydown', 'click', 'scroll', 'touchstart'].forEach(evt => {
    document.addEventListener(evt, () => { lastUserActivity = Date.now(); }, { passive: true });
  });

  setInterval(() => {
    if (typeof isVaultUnlocked !== 'undefined' && isVaultUnlocked && (Date.now() - lastUserActivity > INACTIVITY_TIMEOUT)) {
      if (typeof logout === 'function') {
        logout();
        const errEl = document.getElementById('authError');
        if (errEl) {
          errEl.textContent = '🔒 Sessão encerrada automaticamente por inatividade (15 min).';
          errEl.style.display = 'block';
        }
        if (typeof showToast === 'function') showToast('🔒 Sessão bloqueada por inatividade.');
      }
    }
  }, 15000);

  // 6. Marca d'água na consola
  try {
    console.clear();
    console.log(
      '%c🐍 BLACK MAMBA — SISTEMA PRIVADO\n%cTodos os dados deste site são encriptados com AES-256-GCM.\nTentativas de engenharia reversa ou cópia não autorizada são registadas.',
      'color: #a78bfa; font-size: 16px; font-weight: bold;',
      'color: #ef4444; font-size: 12px;'
    );
  } catch(e) {}
})();

