// ========== CRIPTOGRAFIA & AUTENTICAÇÃO SEGURA ==========
const encText = new TextEncoder();
const decText = new TextDecoder();

async function sha256Hex(str) {
  const hash = await crypto.subtle.digest('SHA-256', encText.encode(str));
  return Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, '0')).join('');
}

async function deriveKek(passcode, saltBytes) {
  const keyMaterial = await crypto.subtle.importKey(
    'raw',
    encText.encode(passcode),
    'PBKDF2',
    false,
    ['deriveKey']
  );
  return crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: saltBytes,
      iterations: 100000,
      hash: 'SHA-256'
    },
    keyMaterial,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt']
  );
}

function hexToBytes(hex) {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < bytes.length; i++) {
    bytes[i] = parseInt(hex.substr(i * 2, 2), 16);
  }
  return bytes;
}

function base64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

function bytesToBase64(bytes) {
  let bin = '';
  for (let i = 0; i < bytes.byteLength; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}

async function decryptVaultWithMek(rawMekBytes) {
  const mek = await crypto.subtle.importKey('raw', rawMekBytes, { name: 'AES-GCM' }, false, ['decrypt']);
  const cipherBytes = base64ToBytes(VAULT.payload);
  const iv = new Uint8Array(VAULT.iv);
  const decryptedBytes = await crypto.subtle.decrypt(
    { name: 'AES-GCM', iv: iv },
    mek,
    cipherBytes
  );
  return JSON.parse(decText.decode(decryptedBytes));
}

async function unlockVaultWithPasscode(passcode) {
  const cleanPass = passcode.trim().toLowerCase();
  const saltBytes = hexToBytes(VAULT.salt);
  const hash = await sha256Hex(cleanPass + ':' + VAULT.salt);

  const slot = VAULT.slots.find(s => s.hash === hash);
  if (!slot) {
    throw new Error('Chave de acesso inválida');
  }

  // Deriva KEK com PBKDF2 (100.000 iterações)
  const kek = await deriveKek(cleanPass, saltBytes);
  const wrappedKeyBytes = new Uint8Array(slot.key);
  const wrapIv = new Uint8Array(slot.iv);

  // Desencripta Master Encryption Key (MEK)
  const rawMekBytes = await crypto.subtle.decrypt(
    { name: 'AES-GCM', iv: wrapIv },
    kek,
    wrappedKeyBytes
  );

  // Desencripta o cofre completo
  const data = await decryptVaultWithMek(new Uint8Array(rawMekBytes));
  return { data, rawMekBytes: new Uint8Array(rawMekBytes) };
}

function applyDecryptedData(data) {
  PRODUCTS = data.products;
  RAW_RECIPES = data.rawRecipes;
  DEFAULT_HEIST_ITEMS = JSON.parse(JSON.stringify(data.heist));
  DEFAULT_PARCERIAS_HTML = data.parceriasHTML;
  HEIST_ITEMS = JSON.parse(JSON.stringify(data.heist));
  isVaultUnlocked = true;

  // Aplica preços customizados guardados de barragens
  applyCustomHeistPrices();

  // Injeta as tabelas de parcerias desencriptadas no DOM
  const parcContainer = document.getElementById('parceriasContainer');
  if (parcContainer) {
    parcContainer.innerHTML = data.parceriasHTML;
  }
  
  // Aplica preços customizados guardados de parcerias
  applyCustomParceriasPrices();

  // Inicializa a aplicação com os dados reais
  initApp();
}

async function checkAuthOnLoad() {
  const savedMekB64 = localStorage.getItem('bm_auth_mek') || sessionStorage.getItem('bm_auth_mek');
  const overlay = document.getElementById('authOverlay');
  const logoutBtn = document.getElementById('logoutBtn');

  if (savedMekB64) {
    try {
      const rawMek = base64ToBytes(savedMekB64);
      const data = await decryptVaultWithMek(rawMek);
      applyDecryptedData(data);
      if (overlay) overlay.style.display = 'none';
      if (logoutBtn) logoutBtn.style.display = 'flex';
      return;
    } catch (e) {
      // Chave guardada inválida ou expirada, pede novamente
      localStorage.removeItem('bm_auth_mek');
      sessionStorage.removeItem('bm_auth_mek');
    }
  }

  // Se não estiver autenticado, exibe o ecrã de bloqueio
  if (overlay) overlay.style.display = 'flex';
  if (logoutBtn) logoutBtn.style.display = 'none';
  setTimeout(() => {
    document.getElementById('authPasscodeInput')?.focus();
  }, 150);
}

const LOCKOUT_KEY = 'bm_sec_lockout';
const FAILS_KEY = 'bm_sec_fails';

function isAuthLockedOut() {
  const lockoutUntil = parseInt(sessionStorage.getItem(LOCKOUT_KEY) || '0');
  const now = Date.now();
  if (lockoutUntil > now) {
    const remainSec = Math.ceil((lockoutUntil - now) / 1000);
    const errEl = document.getElementById('authError');
    if (errEl) {
      errEl.textContent = `🛑 Demasiadas tentativas falhadas. Aguarda ${remainSec}s.`;
      errEl.style.display = 'block';
    }
    return true;
  }
  return false;
}

async function handleAuthSubmit(e) {
  if (e) e.preventDefault();
  const input = document.getElementById('authPasscodeInput');
  const errEl = document.getElementById('authError');
  const card = document.getElementById('authCard');
  const submitBtn = card?.querySelector('.auth-submit-btn');
  const remember = document.getElementById('authRemember')?.checked ?? true;
  const val = (input?.value || '').trim();

  // Bloqueio por tentativas sucessivas falhadas
  if (isAuthLockedOut()) return;

  if (!val) {
    if (errEl) { errEl.textContent = 'Por favor introduz a chave de acesso.'; errEl.style.display = 'block'; }
    return;
  }

  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<span>⏳ A desencriptar...</span>';
  }

  try {
    const { data, rawMekBytes } = await unlockVaultWithPasscode(val);

    // Sucesso: reseta tentativas
    sessionStorage.removeItem(FAILS_KEY);
    sessionStorage.removeItem(LOCKOUT_KEY);

    // Guarda sessão se autorizado
    const mekB64 = bytesToBase64(rawMekBytes);
    if (remember) {
      localStorage.setItem('bm_auth_mek', mekB64);
    } else {
      sessionStorage.setItem('bm_auth_mek', mekB64);
    }

    applyDecryptedData(data);

    if (errEl) errEl.style.display = 'none';
    const overlay = document.getElementById('authOverlay');
    if (overlay) {
      overlay.style.transition = 'opacity 0.3s ease';
      overlay.style.opacity = '0';
      setTimeout(() => {
        overlay.style.display = 'none';
        overlay.style.opacity = '1';
      }, 300);
    }
    const logoutBtn = document.getElementById('logoutBtn');
    if (logoutBtn) logoutBtn.style.display = 'flex';
    showToast('🔓 Cofre desencriptado com sucesso!');
  } catch (err) {
    // Falha: incrementa contador e aplica cooldown progressivo
    let fails = parseInt(sessionStorage.getItem(FAILS_KEY) || '0') + 1;
    sessionStorage.setItem(FAILS_KEY, fails);
    
    let lockDuration = 0;
    if (fails >= 7) lockDuration = 60000;      // 60s
    else if (fails >= 5) lockDuration = 30000; // 30s
    else if (fails >= 3) lockDuration = 10000; // 10s

    if (lockDuration > 0) {
      sessionStorage.setItem(LOCKOUT_KEY, Date.now() + lockDuration);
      isAuthLockedOut();
    } else if (errEl) {
      errEl.textContent = `❌ Chave incorreta (${fails}ª tentativa). Tens mais ${3 - fails} tentativas até bloqueio.`;
      errEl.style.display = 'block';
    }

    if (card) {
      card.classList.remove('shake');
      void card.offsetWidth;
      card.classList.add('shake');
    }
    input?.select();
  } finally {
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.innerHTML = '<span>🔓 Entrar no Sistema</span>';
    }
  }
}

function togglePasscodeVisibility() {
  const input = document.getElementById('authPasscodeInput');
  if (!input) return;
  input.type = input.type === 'password' ? 'text' : 'password';
}

function logout() {
  localStorage.removeItem('bm_auth_mek');
  sessionStorage.removeItem('bm_auth_mek');

  // Limpa os dados confidenciais da memória RAM
  PRODUCTS = [];
  RAW_RECIPES = {};
  HEIST_ITEMS = [];
  isVaultUnlocked = false;

  // Limpa o conteúdo sensível do ecrã
  const pGrid = document.getElementById('productsGrid');
  if (pGrid) pGrid.innerHTML = '';
  const hGrid = document.getElementById('heistItemsGrid');
  if (hGrid) hGrid.innerHTML = '';
  const pCont = document.getElementById('parceriasContainer');
  if (pCont) pCont.innerHTML = '';

  const input = document.getElementById('authPasscodeInput');
  if (input) input.value = '';
  const errEl = document.getElementById('authError');
  if (errEl) errEl.style.display = 'none';

  checkAuthOnLoad();
  showToast('🔒 Sessão terminada. Dados eliminados da memória.');
}

// Renomeia o init original para initApp
function initApp() {
  renderProducts();
  updateSidebarInfo();
  renderHeistItems();
  calcHeistTotal();
  applyCustomParceriasPrices();
}
